package ai.applypilot.identity;
import org.springframework.beans.factory.ObjectProvider; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.HttpStatus; import org.springframework.mail.SimpleMailMessage; import org.springframework.mail.MailException; import org.springframework.mail.javamail.JavaMailSender; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException;
import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.security.SecureRandom; import java.time.Instant; import java.time.temporal.ChronoUnit; import java.util.Base64;
@Service public class PasswordResetService {
 private final UserRepository users; private final PasswordResetTokenRepository tokens; private final RefreshTokenRepository refresh; private final PasswordEncoder passwords; private final ObjectProvider<JavaMailSender> mail; private final String origin; private final String mailHost; private final SecureRandom random=new SecureRandom();
 public PasswordResetService(UserRepository users,PasswordResetTokenRepository tokens,RefreshTokenRepository refresh,PasswordEncoder passwords,ObjectProvider<JavaMailSender> mail,@Value("${app.origin}") String origin,@Value("${spring.mail.host:}") String mailHost){this.users=users;this.tokens=tokens;this.refresh=refresh;this.passwords=passwords;this.mail=mail;this.origin=origin;this.mailHost=mailHost;}
 @Transactional public void request(String email){var sender=mail.getIfAvailable();if(sender==null||mailHost.isBlank())throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Password reset email is not configured");var user=users.findByEmailIgnoreCase(email.trim()).orElse(null);if(user==null)return;byte[] bytes=new byte[32];random.nextBytes(bytes);String token=Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);var message=new SimpleMailMessage();message.setTo(user.getEmail());message.setSubject("Reset your ApplyPilot password");message.setText("Use this link within 30 minutes to reset your password: "+origin+"/#resetToken="+java.net.URLEncoder.encode(token,StandardCharsets.UTF_8));try{sender.send(message);}catch(MailException ignored){return;}tokens.save(new PasswordResetTokenEntity(user,hash(token),Instant.now().plus(30,ChronoUnit.MINUTES)));}
 @Transactional public void confirm(String token,String newPassword){var reset=tokens.findByTokenHash(hash(token)).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Reset link is invalid or expired"));if(!reset.active())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Reset link is invalid or expired");reset.getUser().changePassword(passwords.encode(newPassword));reset.consume();refresh.revokeAllForUser(reset.getUser().getId(),Instant.now());}
 private String hash(String value){try{return java.util.HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
}
